        assert.ok(cmd.indexOf('git push https://x-access-token:' + TOK + '@github.com/' + FORK + '.git') !== -1,
            'the push targets the FORK built from head.repo.full_name');
        assert.ok(cmd.indexOf('@github.com/' + BASE + '.git') === -1,
