function forkHeadFull(headRepoFull, baseOwner, baseRepo) {
   // gh-1070 rework: the same-repo comparison is CASE-INSENSITIVE —
   // the base side comes from config (effectiveRepoInfo.owner/repo)
   // while headRepoFull comes from the API's head.repo.full_name,
   // and GitHub repo names are case-insensitive. A casing drift
   // (config 'istin/dmtools-agents' vs API 'IstiN/dmtools-agents')
   // must NOT misroute a same-repo PR into the fork paths (a false
   // guest park when maintainer_can_modify=false — the exact class
   // of silent misroute gh-1059 eliminated). The fork's own casing is
   // preserved for the push URL.
   var full = String(headRepoFull || '');
   if (full.indexOf('/') === -1) return null;
   var baseFull = (String(baseOwner || '') + '/' + String(baseRepo || '')).toLowerCase();
   return full.toLowerCase() !== baseFull ? full : null;
}
```

