        var n = 0;
        (comments || []).forEach(function (c) {
            var m = /silent-update failure — attempt (\d+)/g.exec(String((c && c.body) || ''));
            if (m) n = Math.max(n, parseInt(m[1], 10));
        });
        return n;
    }

