       // depth, --no-edit flags, new skip conditions) lands in BOTH
       // paths by construction. The two parameterizable seams are
       // (a) how the head is obtained and (b) the push target:
       //
       //  headFlags  — the git clone flags that materialize the head
       //                ('--single-branch --branch <b>' rides the clone
       //                itself for a base head; a fork head clones
       //                branchless and fetches refs/pull/<N>/head)
       //  headSetup  — the post-clone chain that checks the head out
       //                (' for the base path)
       //  pushTarget — the full push destination ('<base-url> <b>'
       //                vs '<fork-url> HEAD:<b>')
       //
       // The '--' separator before the git flags is the documented
       // `gh repo clone` form (the fork path had dropped it — drift
       // this unification also fixes).
       function silentUpdateCommand(opts) {
           return 'gh repo clone ' + effectiveRepoInfo.owner + '/' +
                  effectiveRepoInfo.repo + ' + opts.dir +
                  ' -- ' + opts.headFlags +
                  ' && cd ' + opts.dir +
                  opts.headSetup +
