        assert.ok(cmd.indexOf('--branch feat/x') !== -1, 'single-branch clone of the head ref');
        assert.ok(cmd.indexOf('merge --no-edit FETCH_HEAD') !== -1, 'merges fetched main');
        assert.equal(cmd.slice(-'git push https://x-access-token:[REDACTED:Connection String Password]@github.com/epam/dmtools-dart.git feat/x'.length),
            'git push https://x-access-token:[REDACTED:Connection String Password]@github.com/epam/dmtools-dart.git feat/x');
        // No env swap: the push rides the checkout's stored credentials.
