    // Build preamble that shadows dmtools globals with our mocks
    var _testMocks_ = mocks || {};
    var preamble = '';
    for (var k in _testMocks_) {
        if (_testMocks_.hasOwnProperty(k)) {
            preamble += 'var ' + k + ' = _testMocks_["' + k + '"];\n';
